Rules.InvariantScript:
Reset(cmbCHKCCIbloco);
Reset(cmbCHKCCIaeroporto);
Reset(dtpBuscarChkListCCIini);
Reset(dtpBuscarChkListCCIfin);
Reset(txtBuscarCheckListVeiculoCCI);
Reset(cmbCHKCCIveiculos)

If(
    varPerfilUser <> "Base",
    Concurrent(
        ClearCollect(
            col_checkListCCI,
            Filter(
                Sort(
                    'tbl_CHECK-LIST-VEICULO-CCI',
                    ID,
                    SortOrder.Descending
                ),
                DATA >= dtpBuscarChkListCCIini.SelectedDate && DATA <= dtpBuscarChkListCCIfin.SelectedDate
            )
        ),
        ClearCollect(
            col_checkListCCIitens,
            Filter(
                Sort(
                    'tbl_CHECK-LIST-ALL-ITENS',
                    ID,
                    SortOrder.Descending
                ),
                Modulo = var_tituloModulo
            )
        )
    );
    If(
        CountRows(col_checkListCCIitens) > 0,
        Concurrent(
            ClearCollect(
                col_checkListCCIitensEmAtendimento,
                Filter(
                    col_checkListCCIitens,
                    Status.Value = "Em Atendimento" And Modulo = var_tituloModulo
                )
            ),
            ClearCollect(
                col_checkListCCIitensSolucionado,
                Filter(
                    col_checkListCCIitens,
                    Status.Value = "Solucionado" And Modulo = var_tituloModulo
                )
            ),
            ClearCollect(
                col_checkListCCIitensCacelados,
                Filter(
                    Sort(
                        'tbl_CHECK-LIST-ALL-ITENS-CANCELADOS',
                        ID,
                        SortOrder.Descending
                    ),
                    Modulo = var_tituloModulo
                )
            )
        )
    ),
    Concurrent(
        ClearCollect(
            col_checkListCCI,
            Filter(
                Sort(
                    'tbl_CHECK-LIST-VEICULO-CCI',
                    ID,
                    SortOrder.Descending
                ),
                AEROPORTO = cmbCHKCCIaeroporto.Selected.Result
            )
        ),
        ClearCollect(
            col_checkListCCIitens,
            Filter(
                Sort(
                    'tbl_CHECK-LIST-ALL-ITENS',
                    ID,
                    SortOrder.Descending
                ),
                Modulo = var_tituloModulo And Aeroporto = cmbCHKCCIaeroporto.Selected.Result
            )
        )
    ),
    If(
        CountRows(col_checkListCCIitens) > 0,
        Concurrent(
            ClearCollect(
                col_checkListCCIitensEmAtendimento,
                Filter(
                    Sort(
                        'tbl_CHECK-LIST-ALL-ITENS',
                        ID,
                        SortOrder.Descending
                    ),
                    Status.Value = "Em Atendimento" And Modulo = var_tituloModulo And Aeroporto = cmbCHKCCIaeroporto.Selected.Result
                )
            ),
            ClearCollect(
                col_checkListCCIitensSolucionado,
                Filter(
                    Sort(
                        'tbl_CHECK-LIST-ALL-ITENS',
                        ID,
                        SortOrder.Descending
                    ),
                    Status.Value = "Solucionado" And Modulo = var_tituloModulo And Aeroporto = cmbCHKCCIaeroporto.Selected.Result
                )
            ),
            ClearCollect(
                col_checkListCCIitensCacelados,
                Filter(
                    Sort(
                        'tbl_CHECK-LIST-ALL-ITENS-CANCELADOS',
                        ID,
                        SortOrder.Descending
                    ),
                    Modulo = var_tituloModulo And Aeroporto = cmbCHKCCIaeroporto.Selected.Result
                )
            )
        )
    )
);
